 objIData.CreateNewStoredProcedure("SIM_ClassSubject_EditSubjectID");
 string[] par = { "@a", "1", "@b", "2"};
 objIData.AddParameter(par);
// objIData.AddParameter("@NewSubjectID", newSubjectID);
 objIData.ExecNonQuery();

// Open form chọn môn học
Training.frmSelectSubject frmSelect = Training.frmSelectSubject.Instance;
frmSelect.ISMultiSelect = false; // cờ chọn 1 hoặc nhiều
frmSelect.ShowDialog();

if (frmSelect.ItemSelected != null) // nếu có chọn được môn
{
    var obj = new SimsObject.SIM_Class_Subject();
    obj.ClassSubjectID = Convert.ToInt64(drw["ClassSubjectID"]);
    if (!obj.EditSubjectID(frmSelect.ItemSelected.SubjectID)) // gọi store
    {
        ErrorManager.Error(obj.ErrorException.Message);
        return;
    }

    MessageManager.Info("Đã thay đổi môn thành công!");
}

